// Core tests: the 21 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every expected value below was computed by hand from the SPEC's
// rules; the hand derivations are listed in AUTHOR-CHECK.md section 2
// and in HANDOFF.md.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatCents,
  formatRate,
  formatSixSignificant,
  roundHalfUpDiv,
  run,
} from "../public/js/core/currency-converter.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const base = {
  fromCode: "USD",
  toCode: "TWD",
  rate: "31.5",
  amount: "100",
  direction: "a-to-b",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("half-up rounding: exactly half rounds up, just below stays down", () => {
  assert.equal(roundHalfUpDiv(5n, 2n), 3n);
  assert.equal(roundHalfUpDiv(4n, 2n), 2n);
  assert.equal(roundHalfUpDiv(1n, 3n), 0n);
  assert.equal(roundHalfUpDiv(2n, 3n), 1n);
  assert.equal(roundHalfUpDiv(0n, 7n), 0n);
});

test("inverse rate uses 6 significant digits, not 6 decimal places", () => {
  assert.equal(formatSixSignificant(1000000n, 31500000n), "0.031746");
  assert.equal(formatSixSignificant(1000000n, 6600n), "151.515");
  assert.equal(formatSixSignificant(1000000n, 2500000n), "0.4");
  assert.equal(formatSixSignificant(1000000n, 1000000n), "1");
  assert.equal(formatSixSignificant(1000000n, 1n), "1000000");
  assert.equal(formatSixSignificant(1000000n, 1000000000000n), "0.000001");
  assert.equal(formatSixSignificant(1000000n, 3000000n), "0.333333");
  assert.equal(formatSixSignificant(1000000n, 149850000n), "0.00667334");
});

test("inverse rate carry overflow: 999999.5 rounds up to 1000000", () => {
  // inv = 1999999 / 2 = 999999.5; p = 5, m = round(999999.5) = 1000000,
  // so the overflow rule re-records m = 100000 and p = 6: "1000000".
  assert.equal(formatSixSignificant(1999999n, 2n), "1000000");
});

test("reverse conversion divides by the entered rate, never by the displayed inverse", () => {
  // Exact: 999999999 / 3 = 333333333. Via the displayed inverse
  // 0.333333 the product would be 999999999 x 0.333333 = 333332999.67,
  // which rounds to 333333000 — a different answer. The implementation
  // must give the exact-quotient answer.
  const outcome = run({ ...base, rate: "3", amount: "9999999.99", direction: "b-to-a" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.convertedCents, 333333333);
  assert.equal(outcome.result.inverseRate, "0.333333");
});

test("reverse half-up tie: 0.05 / 2 = 2.5 cents rounds up to 3", () => {
  const outcome = run({ ...base, rate: "2", amount: "0.05", direction: "b-to-a" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.convertedCents, 3);
  assert.equal(outcome.result.inverseRate, "0.5");
  assert.deepEqual(outcome.result.quickTable, [
    { amountCents: 100, convertedCents: 200 },
    { amountCents: 1000, convertedCents: 2000 },
    { amountCents: 10000, convertedCents: 20000 },
    { amountCents: 100000, convertedCents: 200000 },
  ]);
});

test("boundary: maximum amount at the default rate", () => {
  // 999999999 cents x 31.5 = 31499999968.5 cents -> half-up 31499999969.
  const outcome = run({ ...base, amount: "9999999.99" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.amountCents, 999999999);
  assert.equal(outcome.result.convertedCents, 31499999969);
  assert.equal(outcome.result.inverseRate, "0.031746");
});

test("boundary: just over the amount cap is RANGE", () => {
  assert.deepEqual(errorOf({ ...base, amount: "10000000" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
});

test("boundary: minimum rate with the maximum amount", () => {
  // 999999999 x 1 / 10^6 = 999.999999 -> 1000; quick table all 0.
  const outcome = run({ ...base, rate: "0.000001", amount: "9999999.99" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.convertedCents, 1000);
  assert.equal(outcome.result.inverseRate, "1000000");
  assert.deepEqual(outcome.result.quickTable, [
    { amountCents: 100, convertedCents: 0 },
    { amountCents: 1000, convertedCents: 0 },
    { amountCents: 10000, convertedCents: 0 },
    { amountCents: 100000, convertedCents: 0 },
  ]);
});

test("boundary: maximum rate, reverse direction", () => {
  // 10000 x 10^6 / 10^12 = 0.01 -> 0.
  const outcome = run({ ...base, rate: "1000000", direction: "b-to-a" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.convertedCents, 0);
  assert.equal(outcome.result.inverseRate, "0.000001");
  assert.deepEqual(outcome.result.quickTable, [
    { amountCents: 100, convertedCents: 100000000 },
    { amountCents: 1000, convertedCents: 1000000000 },
    { amountCents: 10000, convertedCents: 10000000000 },
    { amountCents: 100000, convertedCents: 100000000000 },
  ]);
});

test("rate grammar: trailing zeros and 6 decimals pass; 7 decimals, leading zeros, signs and junk fail", () => {
  const ok = run({ ...base, rate: "31.50" });
  assert.equal(ok.ok, true);
  assert.equal(ok.result.rateMicro, 31500000);
  const six = run({ ...base, rate: "0.123456" });
  assert.equal(six.ok, true);
  assert.equal(six.result.rateMicro, 123456);
  for (const bad of ["31.1234567", "31.", ".5", "031.5", "-31.5", "+31.5", "3.15e1", "31,5", "31.5 ", "３１.５"]) {
    assert.deepEqual(errorOf({ ...base, rate: bad }), {
      code: "DECIMAL_FORMAT",
      field: "rate",
      row: null,
    });
  }
  // "0.000000" is grammatically valid but out of range.
  assert.deepEqual(errorOf({ ...base, rate: "0.000000" }), {
    code: "RANGE",
    field: "rate",
    row: null,
  });
});

test("amount grammar: 0.00 and 100.00 pass; leading zeros, signs, exponents and junk fail", () => {
  assert.equal(run({ ...base, amount: "0.00" }).result.convertedCents, 0);
  assert.equal(run({ ...base, amount: "100.00" }).result.convertedCents, 315000);
  for (const bad of ["0100", "10.005", "10.", ".5", "-100", "+100", "1e2", "100 ", "１００"]) {
    assert.deepEqual(errorOf({ ...base, amount: bad }), {
      code: "DECIMAL_FORMAT",
      field: "amount",
      row: null,
    });
  }
});

test("capacity: an over-long value is INPUT_LIMIT on every field, before grammar and range", () => {
  assert.deepEqual(errorOf({ ...base, fromCode: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "fromCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, toCode: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "toCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rate: "123456789012345" }), {
    code: "INPUT_LIMIT",
    field: "rate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, direction: "a-to-b-to-" }), {
    code: "INPUT_LIMIT",
    field: "direction",
    row: null,
  });
  // A 13-unit amount is INPUT_LIMIT even though it would also be out of range.
  assert.deepEqual(errorOf({ ...base, amount: "9999999999999" }), {
    code: "INPUT_LIMIT",
    field: "amount",
    row: null,
  });
});

test("a lone surrogate is UNICODE on every field; a paired surrogate fails grammar instead", () => {
  assert.deepEqual(errorOf({ ...base, fromCode: "\uD800" }), {
    code: "UNICODE",
    field: "fromCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rate: "\uD800" }), {
    code: "UNICODE",
    field: "rate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, amount: "\uD800" }), {
    code: "UNICODE",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, direction: "\uD800" }), {
    code: "UNICODE",
    field: "direction",
    row: null,
  });
  // A well-formed surrogate pair is not UNICODE; it fails the grammar.
  assert.deepEqual(errorOf({ ...base, rate: "31.5\uD83D\uDE00" }), {
    code: "DECIMAL_FORMAT",
    field: "rate",
    row: null,
  });
});

test("EMPTY fires on every field before grammar", () => {
  assert.deepEqual(errorOf({ ...base, fromCode: "" }), {
    code: "EMPTY",
    field: "fromCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rate: "" }), {
    code: "EMPTY",
    field: "rate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, amount: "" }), {
    code: "EMPTY",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, direction: "" }), {
    code: "EMPTY",
    field: "direction",
    row: null,
  });
});

test("code grammar: digits, mixed case handling, and 2-letter codes", () => {
  assert.deepEqual(errorOf({ ...base, fromCode: "US1" }), {
    code: "CODE_FORMAT",
    field: "fromCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, fromCode: "US" }), {
    code: "CODE_FORMAT",
    field: "fromCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, toCode: "TWD " }), {
    code: "CODE_FORMAT",
    field: "toCode",
    row: null,
  });
  const mixed = run({ ...base, fromCode: "uSd", toCode: "tWd" });
  assert.equal(mixed.ok, true);
  assert.equal(mixed.result.fromCode, "USD");
  assert.equal(mixed.result.toCode, "TWD");
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, fromCode: "USDT", rate: "bad" }), {
    code: "CODE_FORMAT",
    field: "fromCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, toCode: "USDT", rate: "bad" }), {
    code: "CODE_FORMAT",
    field: "toCode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, rate: "bad", amount: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "rate",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, amount: "bad", direction: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "amount",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.rate;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, rate: 31.5 }), schema);
  assert.deepEqual(errorOf({ ...base, amount: null }), schema);
  assert.deepEqual(errorOf(["USD"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("USD"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "rate", {
    enumerable: true,
    get() {
      return "31.5";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...base };
  stringObject.rate = new String("31.5");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("the core does not mutate its input", () => {
  const input = { ...base };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...base, rate: "0" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("property: forward conversion never decreases as the amount or the rate grows", () => {
  let previous = -Infinity;
  for (const amount of ["0", "1", "10", "100", "1000", "9999999.99"]) {
    const outcome = run({ ...base, amount });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.convertedCents >= previous);
    previous = outcome.result.convertedCents;
  }
  previous = -Infinity;
  for (const rate of ["0.000001", "0.0066", "1", "31.5", "149.85", "1000000"]) {
    const outcome = run({ ...base, rate });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.convertedCents >= previous);
    previous = outcome.result.convertedCents;
  }
});

test("display formatting: cents with two decimals, rates with trailing zeros stripped", () => {
  assert.equal(formatCents(0), "0.00");
  assert.equal(formatCents(1), "0.01");
  assert.equal(formatCents(99), "0.99");
  assert.equal(formatCents(100), "1.00");
  assert.equal(formatCents(315000), "3150.00");
  assert.equal(formatCents(100000000), "1000000.00");
  assert.equal(formatRate(31500000), "31.5");
  assert.equal(formatRate(6600), "0.0066");
  assert.equal(formatRate(1000000), "1");
  assert.equal(formatRate(149850000), "149.85");
  assert.equal(formatRate(1), "0.000001");
  assert.equal(formatRate(1000000000000), "1000000");
  assert.equal(formatRate(2500000), "2.5");
  assert.equal(formatRate(1001000), "1.001");
});
